CREATE TABLE IF NOT EXISTS "buyer_profiles" (
    "id" TEXT NOT NULL,
    "businessId" TEXT NOT NULL,
    "industrySegment" TEXT,
    "procurementCategories" TEXT[],
    "materialsOfInterest" TEXT[],
    "annualBudget" TEXT,
    "purchaseFrequency" TEXT,
    "projectLocations" JSONB,
    "shippingAddresses" JSONB,
    "billingAddresses" JSONB,
    "approvalContacts" JSONB,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "buyer_profiles_pkey" PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "supplier_profiles" (
    "id" TEXT NOT NULL,
    "businessId" TEXT NOT NULL,
    "supplierType" TEXT NOT NULL,
    "operatingCategories" TEXT[],
    "subcategories" TEXT[],
    "brandsOffered" TEXT[],
    "manufacturingCapacity" TEXT,
    "monthlySupplyCapacity" TEXT,
    "minimumOrderValue" INTEGER,
    "warehouseLocations" JSONB,
    "serviceableDistricts" TEXT[],
    "serviceableStates" TEXT[],
    "panIndiaDelivery" BOOLEAN NOT NULL DEFAULT false,
    "standardLeadTimeDays" INTEGER DEFAULT 3,
    "fleetDetails" TEXT,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "supplier_profiles_pkey" PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "ValuationRequest" (
    "id" TEXT NOT NULL,
    "referenceNo" TEXT NOT NULL,
    "userId" TEXT NOT NULL,
    "status" "ValuationRequestStatus" NOT NULL DEFAULT 'PENDING_PAYMENT',
    "propertyType" "RealEstateType" NOT NULL DEFAULT 'APARTMENT',
    "state" TEXT NOT NULL DEFAULT 'Gujarat',
    "city" TEXT NOT NULL DEFAULT 'Ahmedabad',
    "localityId" TEXT NOT NULL,
    "microLocation" TEXT,
    "projectId" TEXT,
    "buildingName" TEXT,
    "address" TEXT NOT NULL,
    "pincode" TEXT NOT NULL,
    "bhk" DOUBLE PRECISION NOT NULL,
    "carpetAreaSqFt" DOUBLE PRECISION NOT NULL,
    "builtUpAreaSqFt" DOUBLE PRECISION,
    "superBuiltUpAreaSqFt" DOUBLE PRECISION,
    "areaUnit" TEXT NOT NULL DEFAULT 'sqft',
    "floor" INTEGER,
    "totalFloors" INTEGER,
    "propertyAgeYears" INTEGER,
    "condition" "PropertyCondition",
    "furnishingStatus" "FurnishingStatus",
    "parkingSpaces" INTEGER NOT NULL DEFAULT 0,
    "amenitiesJson" JSONB,
    "possessionStatus" TEXT,
    "transactionContext" "TransactionContext" NOT NULL DEFAULT 'BUYING',
    "askingPriceLakhs" DOUBLE PRECISION,
    "targetOfferLakhs" DOUBLE PRECISION,
    "ownerName" TEXT,
    "contactPhone" TEXT,
    "notes" TEXT,
    "rejectionReason" TEXT,
    "processingLockToken" TEXT,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "ValuationRequest_pkey" PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "ValuationPayment" (
    "id" TEXT NOT NULL,
    "requestId" TEXT NOT NULL,
    "userId" TEXT NOT NULL,
    "amountPaise" INTEGER NOT NULL,
    "currency" TEXT NOT NULL DEFAULT 'INR',
    "status" "ValuationPaymentStatus" NOT NULL DEFAULT 'PENDING',
    "provider" TEXT NOT NULL DEFAULT 'RAZORPAY',
    "orderId" TEXT,
    "paymentId" TEXT,
    "signature" TEXT,
    "idempotencyKey" TEXT NOT NULL,
    "receiptNumber" TEXT,
    "rawResponseJson" JSONB,
    "paidAt" TIMESTAMP(3),
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "ValuationPayment_pkey" PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "ValuationRefund" (
    "id" TEXT NOT NULL,
    "paymentId" TEXT NOT NULL,
    "amountPaise" INTEGER NOT NULL,
    "reason" TEXT NOT NULL,
    "status" "ValuationRefundStatus" NOT NULL DEFAULT 'INITIATED',
    "refundReference" TEXT,
    "processedBy" TEXT,
    "processedAt" TIMESTAMP(3),
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "ValuationRefund_pkey" PRIMARY KEY ("id")
);

